from rdkit import Chem
from rdkit.Chem import AllChem

smi = "CC(C)CCCCCCCCC/C=C/C(=O)N[C@H]1[C@H](O)[C@@H](O)[C@H](C[C@@H](O)[C@H]2O[C@@H](n3ccc(=O)[nH]c3=O)[C@@H](O)[C@H]2O)O[C@@H]1O[C@@H]4O[C@H](CO)[C@@H](O)[C@H](O)[C@@H]4NC(C)=O"
m = Chem.MolFromSmiles(smi)
print("atoms:", m.GetNumAtoms())
print("formula:", Chem.rdMolDescriptors.CalcMolFormula(m))

# expected targets: atom_idx -> target CIP
targets = {17:'R',18:'R',20:'S',22:'R',24:'R',26:'R',28:'R',37:'R',39:'S',42:'S',44:'R',46:'R',49:'S',51:'R',53:'R'}

def get_cips(mol):
    Chem.AssignStereochemistry(mol, cleanIt=True, force=True)
    d={}
    for a in mol.GetAtoms():
        if a.HasProp('_CIPCode'):
            d[a.GetIdx()] = a.GetProp('_CIPCode')
    return d

cips = get_cips(m)
for i,t in targets.items():
    print(i, m.GetAtomWithIdx(i).GetSymbol(), "target", t, "got", cips.get(i))
